import 'package:flutter/material.dart';import '../../widgets/media/local_media_image.dart';import 'package:image_picker/image_picker.dart';import 'package:uuid/uuid.dart';import '../../services/demo_store.dart';import '../../models/media_post.dart';import '../../widgets/countdown/countdown.dart';
class PartyScreen extends StatefulWidget{final String partyId;const PartyScreen({super.key,required this.partyId});@override State<PartyScreen>createState()=>_PartyScreenState();}
class _PartyScreenState extends State<PartyScreen>{final s=DemoStore.instance;@override void initState(){super.initState();s.init();s.addListener(_up);}@override void dispose(){s.removeListener(_up);super.dispose();}void _up(){if(mounted)setState((){});}Future<void>pick(bool camera)async{final x=await (camera?ImagePicker().pickImage(source:ImageSource.camera,imageQuality:90):ImagePicker().pickMedia());if(x==null)return;final p=s.getParty(widget.partyId);if(p==null)return;final m=MediaPost(id:const Uuid().v4(),partyId:p.id,userId:'demo-user',type:_isVideo(x)?'video':'image',localPath:x.path,caption:null,createdAt:DateTime.now().toUtc(),username:'you',displayName:'You');s.addMedia(m);}bool _isVideo(XFile x)=>(x.mimeType??'').startsWith('video/')||RegExp(r'\.(mp4|mov|m4v|webm)$',caseSensitive:false).hasMatch(x.name);
@override Widget build(BuildContext c){final p=s.getParty(widget.partyId);if(p==null)return const Scaffold(body:Center(child:Text('Party no longer available')));final posts=s.media[p.id]??[];final ended=DateTime.now().toUtc().isAfter(p.endAt);return Scaffold(appBar:AppBar(title:Text(p.title),actions:[IconButton(onPressed:()=>showModalBottomSheet(context:c,builder:(_)=>_ShareSheet(p.title,p.id)),icon:const Icon(Icons.share))]),body:RefreshIndicator(onRefresh:()async=>setState((){}),child:ListView(padding:const EdgeInsets.all(16),children:[Text(p.title,style:Theme.of(c).textTheme.headlineSmall?.copyWith(fontWeight:FontWeight.bold)),const SizedBox(height:8),Text(p.description??''),const SizedBox(height:16),Card(child:Padding(padding:const EdgeInsets.all(18),child:Row(children:[PartyCountdown(startAt:p.startAt,endAt:p.endAt,style:p.countdownStyle),const Spacer(),Column(children:[Text('${posts.length}',style:Theme.of(c).textTheme.titleLarge),const Text('posts')])]))),const SizedBox(height:16),if(!ended)Row(children:[Expanded(child:FilledButton.icon(onPressed:()=>pick(false),icon:const Icon(Icons.photo_library),label:const Text('Add Photo / Video'))),const SizedBox(width:8),IconButton.filled(onPressed:()=>pick(true),icon:const Icon(Icons.camera_alt))])else const Padding(padding:EdgeInsets.all(12),child:Text('This Party has ended. New uploads are closed; existing memories remain available.')),const SizedBox(height:12),...posts.map((m)=>Card(clipBehavior:Clip.antiAlias,child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[if(m.localPath!=null)LocalMediaImage(path:m.localPath!,video:m.type=='video',height:260),ListTile(leading:const CircleAvatar(child:Icon(Icons.person)),title:Text(m.displayName??'You'),subtitle:Text('❤️ ${m.likeCount}   💬 ${m.commentCount}'),trailing:IconButton(onPressed:()=>s.toggleLike(m),icon:Icon(m.liked?Icons.favorite:Icons.favorite_border)))]))) ])));}}
class _ShareSheet extends StatelessWidget{final String title,id;const _ShareSheet(this.title,this.id);@override Widget build(BuildContext c)=>SafeArea(child:Padding(padding:const EdgeInsets.all(20),child:Column(mainAxisSize:MainAxisSize.min,children:[Text(title,style:Theme.of(c).textTheme.titleLarge),const SizedBox(height:10),SelectText('https://picparty.app/p/$id'),const SizedBox(height:10),const Text('QR code and native deep links are wired for production Supabase configuration.')])));}
